import{_ as e,c as l,o as i,ae as t}from"./chunks/framework.DNEoaTf_.js";const c=JSON.parse('{"title":"使い方","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/index.md","filePath":"ja/guide/index.md"}'),o={name:"ja/guide/index.md"};function r(h,a,n,u,s,d){return i(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="使い方" tabindex="-1">使い方 <a class="header-anchor" href="#使い方" aria-label="Permalink to &quot;使い方&quot;">​</a></h1><h2 id="基本的な使い方" tabindex="-1">基本的な使い方 <a class="header-anchor" href="#基本的な使い方" aria-label="Permalink to &quot;基本的な使い方&quot;">​</a></h2><h3 id="ツールバーアイコンから表示" tabindex="-1">ツールバーアイコンから表示 <a class="header-anchor" href="#ツールバーアイコンから表示" aria-label="Permalink to &quot;ツールバーアイコンから表示&quot;">​</a></h3><ol><li>YouTube で動画を再生</li><li>ブラウザのツールバーにある拡張機能アイコンをクリック</li><li>現在再生中の動画のサムネイルがポップアップで表示されます</li></ol><h3 id="youtube-ページ上で表示" tabindex="-1">YouTube ページ上で表示 <a class="header-anchor" href="#youtube-ページ上で表示" aria-label="Permalink to &quot;YouTube ページ上で表示&quot;">​</a></h3><p>YouTube の視聴ページ（チャンネルアイコンの横）に、サムネイル画像が自動的に追加表示されます。</p><ul><li>サムネイル画像をクリックすると、詳細確認画面（Thumbnail View）が開きます</li></ul><h2 id="thumbnail-view-詳細表示" tabindex="-1">Thumbnail View（詳細表示） <a class="header-anchor" href="#thumbnail-view-詳細表示" aria-label="Permalink to &quot;Thumbnail View（詳細表示）&quot;">​</a></h2><h3 id="全サイズ・全フォーマットの一覧表示" tabindex="-1">全サイズ・全フォーマットの一覧表示 <a class="header-anchor" href="#全サイズ・全フォーマットの一覧表示" aria-label="Permalink to &quot;全サイズ・全フォーマットの一覧表示&quot;">​</a></h3><p>「Thumbnail View」タブでは、その動画のサムネイルを網羅的に確認できます：</p><h4 id="解像度-サイズ" tabindex="-1">解像度（サイズ） <a class="header-anchor" href="#解像度-サイズ" aria-label="Permalink to &quot;解像度（サイズ）&quot;">​</a></h4><ul><li><strong>maxresdefault</strong>: 最大画質（1280x720 または 1920x1080）</li><li><strong>sddefault</strong>: 標準画質（640x480）</li><li><strong>hqdefault</strong>: 高画質（480x360）</li><li><strong>mqdefault</strong>: 中画質（320x180）</li><li><strong>default</strong>: 低画質（120x90）</li></ul><h4 id="フォーマット" tabindex="-1">フォーマット <a class="header-anchor" href="#フォーマット" aria-label="Permalink to &quot;フォーマット&quot;">​</a></h4><ul><li><strong>JPG</strong>: JPEG 形式</li><li><strong>WebP</strong>: WebP 形式</li></ul><h3 id="サムネイルのダウンロード" tabindex="-1">サムネイルのダウンロード <a class="header-anchor" href="#サムネイルのダウンロード" aria-label="Permalink to &quot;サムネイルのダウンロード&quot;">​</a></h3><ol><li>Thumbnail View で目的のサムネイルを選択</li><li>画像を右クリック</li><li><strong>名前を付けて画像を保存</strong> を選択</li></ol><p>または、画像をクリックして新しいタブで開き、そこから保存することもできます。</p><h2 id="youtube-shorts-への対応" tabindex="-1">YouTube Shorts への対応 <a class="header-anchor" href="#youtube-shorts-への対応" aria-label="Permalink to &quot;YouTube Shorts への対応&quot;">​</a></h2><p>通常の動画と同じ操作で、YouTube Shorts のサムネイルも取得できます：</p><ol><li>Shorts を再生</li><li>ツールバーアイコンをクリック、またはページ上のサムネイルをクリック</li><li>Shorts のサムネイルが表示されます</li></ol><h2 id="活用例" tabindex="-1">活用例 <a class="header-anchor" href="#活用例" aria-label="Permalink to &quot;活用例&quot;">​</a></h2><h3 id="クリエイター向け" tabindex="-1">クリエイター向け <a class="header-anchor" href="#クリエイター向け" aria-label="Permalink to &quot;クリエイター向け&quot;">​</a></h3><ul><li>自分の動画のサムネイルを確認</li><li>競合チャンネルのサムネイルデザインを研究</li><li>全解像度でのサムネイル表示を確認</li></ul><h3 id="一般ユーザー向け" tabindex="-1">一般ユーザー向け <a class="header-anchor" href="#一般ユーザー向け" aria-label="Permalink to &quot;一般ユーザー向け&quot;">​</a></h3><ul><li>気に入った動画のサムネイルを保存</li><li>高画質のサムネイル画像をダウンロード</li><li>WebP 形式でのサムネイルを取得</li></ul><div class="tip custom-block"><p class="custom-block-title">ヒント</p><p>maxresdefault（最大画質）は、すべての動画で利用可能とは限りません。動画によっては、低解像度のサムネイルのみ存在する場合があります。</p></div>',26)])])}const m=e(o,[["render",r]]);export{c as __pageData,m as default};
